/**
 * The Covenant
 * ------------
 * Noah builds an altar, offers burnt offerings, and the Lord sets the rainbow in the cloud as a sign of the covenant. Stage: an altar of stone on a mountain, the smoke rising, the sky clearing, a rainbow across the whole earth; a promise being made in colour and light.
 *
 * Palette 0x141e2e → 0x081018 · light: rainbow · hero: altar
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./noah-kit.js.
 */

import { THREE, createScene, rain, altar, flame, person, birds } from './noah-kit.js';

const BG = 0x141e2e;
const GROUND = 0x020508;

export function build(group) {
    const W = createScene(group, { seed: 32221839, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — rainbow */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-30, 70, -150], 10, 0xfff8e8);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-40, 44, -125, 26], [30, 50, -135, 32], [85, 42, -120, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xf0f4f8, { opacity: 0.75 }), [x, y, z], { s: [s, s * 0.22, s * 0.5] });
    });
    W.backdrop(clouds);

    /* ground */
    W.ground(260, 260, 0, 0, 0x020508, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* hills: angular ridges on the horizon */
    const hills = W.grp(group, [0, 0, 0], { name: 'hills' });
    for (let i = 0; i < 9; i++) {
        const x = -130 + i * 32 + W.rr(-8, 8);
        W.add(hills, W.G('cone', W.rr(14, 28), W.rr(10, 24), 5), W.mat(0x020406), [x, 0, -95 - W.rr(0, 25)], { r: [0, W.r() * 3, 0] });
    }
    W.backdrop(hills);

    /* storm: rain sheets across the whole frame */
    rain(W, group, 900, 230, 65, 16);

    /* hero: the altar */
    altar(W, group, 0, 0, 0, 1.4, { stone: 0x081119 });

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x141e2e, ry: -0.43, s: 1.15 });

    /* birds: slow circles high above */
    birds(W, group, 8, 55, { y: 26 });

    return W.finish();
}

export default { build };
